async function getActiveSubscription(userId: string): Promise<Subscription | null> {
  const query = 'SELECT * FROM subscriptions WHERE user_id = $1';
  const rows = await db.query(query, [userId]);
  if (rows.length === 0) return null;
  const row = rows[0];
  const validUntil = new Date(row.valid_until);
  if (validUntil < new Date()) return null;
  return {
    userId: row.user_id,
    tier: row.tier,
    validUntil,
    features: JSON.parse(row.features)
  };
}

export async function hasFeatureAccess(userId: string, feature: string): Promise<boolean> {
  const subscription = await getActiveSubscription(userId);
  return subscription ? subscription.features.includes(feature) : false;
}
